CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role = 'admin'), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_directory_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_directory_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_directory_admin() TO authenticated;
CREATE TABLE public.agencies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, trade_name text, name_ar text, activity_fr text, activity_ar text, logo_url text, cover_url text, summary_fr text, summary_ar text, description_fr text, description_ar text, services text[] NOT NULL DEFAULT '{}', offerings_fr text[] NOT NULL DEFAULT '{}', offerings_ar text[] NOT NULL DEFAULT '{}', phone text, email text, website text, address text, address_ar text, city text, coverage_cities text[] NOT NULL DEFAULT '{}', is_partner boolean NOT NULL DEFAULT false, is_verified boolean NOT NULL DEFAULT false, clients_generated integer NOT NULL DEFAULT 0, show_stats boolean NOT NULL DEFAULT true, published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 100, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.agencies TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agencies TO authenticated; GRANT ALL ON public.agencies TO service_role;
ALTER TABLE public.agencies ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published agencies" ON public.agencies FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY "Admin manage agencies" ON public.agencies FOR ALL TO authenticated USING(public.is_directory_admin()) WITH CHECK(public.is_directory_admin());
CREATE TABLE public.agency_offerings (slug text PRIMARY KEY, category text NOT NULL, label_fr text NOT NULL UNIQUE, label_ar text NOT NULL, audience text NOT NULL DEFAULT 'professionals');
GRANT SELECT ON public.agency_offerings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agency_offerings TO authenticated; GRANT ALL ON public.agency_offerings TO service_role;
ALTER TABLE public.agency_offerings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public offerings" ON public.agency_offerings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin manage offerings" ON public.agency_offerings FOR ALL TO authenticated USING(public.is_directory_admin()) WITH CHECK(public.is_directory_admin());
CREATE TABLE public.agency_offering_links (agency_slug text REFERENCES public.agencies(slug) ON DELETE CASCADE ON UPDATE CASCADE, offering_slug text REFERENCES public.agency_offerings(slug) ON DELETE CASCADE, PRIMARY KEY(agency_slug,offering_slug));
GRANT SELECT ON public.agency_offering_links TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agency_offering_links TO authenticated; GRANT ALL ON public.agency_offering_links TO service_role;
ALTER TABLE public.agency_offering_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published offering links" ON public.agency_offering_links FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.agencies a WHERE a.slug=agency_slug AND a.published));
CREATE POLICY "Admin manage links" ON public.agency_offering_links FOR ALL TO authenticated USING(public.is_directory_admin()) WITH CHECK(public.is_directory_admin());
CREATE TABLE public.agency_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL CHECK(length(full_name) BETWEEN 1 AND 120), phone text NOT NULL CHECK(length(phone) BETWEEN 6 AND 40), email text NOT NULL CHECK(length(email) BETWEEN 3 AND 160), city text NOT NULL CHECK(length(city) BETWEEN 1 AND 80), offering_slug text NOT NULL REFERENCES public.agency_offerings(slug), need_details text NOT NULL CHECK(length(need_details) BETWEEN 10 AND 2000), source_agency text REFERENCES public.agencies(slug), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','qualified','closed')), qualification_notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.agency_opportunities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agency_opportunities TO authenticated; GRANT ALL ON public.agency_opportunities TO service_role;
ALTER TABLE public.agency_opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Submit pending request" ON public.agency_opportunities FOR INSERT TO anon,authenticated WITH CHECK(status='pending' AND qualification_notes='');
CREATE POLICY "Admin manage requests" ON public.agency_opportunities FOR ALL TO authenticated USING(public.is_directory_admin()) WITH CHECK(public.is_directory_admin());
CREATE TABLE public.agency_opportunity_recipients (opportunity_id uuid REFERENCES public.agency_opportunities(id) ON DELETE CASCADE, agency_slug text REFERENCES public.agencies(slug), selected_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, PRIMARY KEY(opportunity_id,agency_slug));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.agency_opportunity_recipients TO authenticated; GRANT ALL ON public.agency_opportunity_recipients TO service_role;
ALTER TABLE public.agency_opportunity_recipients ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin manage recipients" ON public.agency_opportunity_recipients FOR ALL TO authenticated USING(public.is_directory_admin()) WITH CHECK(public.is_directory_admin());
CREATE FUNCTION public.validate_agency_recipient() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE req public.agency_opportunities; BEGIN SELECT * INTO req FROM public.agency_opportunities WHERE id=NEW.opportunity_id FOR UPDATE; IF req.status <> 'qualified' THEN RAISE EXCEPTION 'Qualification required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.agencies a JOIN public.agency_offering_links l ON l.agency_slug=a.slug WHERE a.slug=NEW.agency_slug AND a.published AND req.city=ANY(a.coverage_cities) AND l.offering_slug=req.offering_slug) THEN RAISE EXCEPTION 'Incompatible agency'; END IF; IF (SELECT count(*) FROM public.agency_opportunity_recipients WHERE opportunity_id=NEW.opportunity_id)>=3 THEN RAISE EXCEPTION 'Maximum three recipients'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_recipient BEFORE INSERT ON public.agency_opportunity_recipients FOR EACH ROW EXECUTE FUNCTION public.validate_agency_recipient();
CREATE FUNCTION public.prevent_recipient_reassignment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.opportunity_id<>OLD.opportunity_id OR NEW.agency_slug<>OLD.agency_slug THEN RAISE EXCEPTION 'Recipient identity cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prevent_recipient_reassignment BEFORE UPDATE ON public.agency_opportunity_recipients FOR EACH ROW EXECUTE FUNCTION public.prevent_recipient_reassignment();
CREATE TABLE public.agency_contact_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agency_slug text NOT NULL REFERENCES public.agencies(slug), channel text NOT NULL CHECK(channel IN ('phone','website','whatsapp')), visitor_id text NOT NULL CHECK(length(visitor_id) BETWEEN 1 AND 120), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.agency_contact_events TO anon,authenticated; GRANT ALL ON public.agency_contact_events TO service_role;
ALTER TABLE public.agency_contact_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Log published contact" ON public.agency_contact_events FOR INSERT TO anon,authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.agencies WHERE slug=agency_slug AND published));
CREATE FUNCTION public.agency_contact_counts() RETURNS TABLE(agency_slug text,contacts bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.agency_slug,count(DISTINCT e.visitor_id) FROM public.agency_contact_events e JOIN public.agencies a ON a.slug=e.agency_slug AND a.published GROUP BY e.agency_slug $$;
REVOKE ALL ON FUNCTION public.agency_contact_counts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.agency_contact_counts() TO anon,authenticated;